def switch_unissued_water_policy(apps, schema_editor):
    """Keep issued invoices and original rates intact; only convert unissued drafts."""
    alias = schema_editor.connection.alias
    Rate = apps.get_model('billing', 'UtilityRate')
    Draft = apps.get_model('billing', 'InvoiceDraft')
    Member = apps.get_model('rooms', 'ContractTenant')
    today = timezone.localdate()
    rates = Rate.objects.using(alias)
    current = rates.filter(effective_date__lte=today).order_by('-effective_date', '-pk').first()
    # Preserve scheduled electricity prices as well as their original historical rows.
    future = list(rates.filter(effective_date__gt=today).order_by('effective_date', 'pk'))
    if current:
        rates.create(electric_price=current.electric_price, water_price=50000,
                     effective_date=today, water_billing_method='per_person')
    for rate in future:
        rates.create(electric_price=rate.electric_price, water_price=50000,
                     effective_date=rate.effective_date, water_billing_method='per_person')
    for draft in Draft.objects.using(alias).filter(invoice__isnull=True).iterator():
        count = Member.objects.using(alias).filter(contract_id=draft.contract_id).count()
        Draft.objects.using(alias).filter(pk=draft.pk).update(
            water_billing_method='per_person', water_unit_price=50000,
            water_people_count=count or None, old_water=None, new_water=None,
            revision=draft.revision + 1)


